from pymonet.either import Either
from pymonet.lazy import Lazy


def _get_lazy_value(lazy):
    if hasattr(lazy, "get"):
        try:
            return lazy.get()
        except TypeError:
            pass
    for attr in ("fn", "func", "constructor_fn", "_fn", "value", "_value"):
        if hasattr(lazy, attr):
            candidate = getattr(lazy, attr)
            if callable(candidate):
                try:
                    return candidate()
                except Exception:
                    continue
            return candidate
    raise AssertionError("Unable to resolve Lazy value")


def test_either_to_lazy_returns_lazy_instance():
    either = Either(42)
    result = either.to_lazy()
    assert isinstance(result, Lazy)


def test_either_to_lazy_preserves_value():
    either = Either("hello")
    lazy = either.to_lazy()
    assert isinstance(lazy, Lazy)
    assert _get_lazy_value(lazy) == "hello"


def test_either_to_lazy_references_either_value(monkeypatch):
    either = Either(1)
    lazy = either.to_lazy()
    assert isinstance(lazy, Lazy)
    assert _get_lazy_value(lazy) == 1
    monkeypatch.setattr(either, "value", 2)
    assert _get_lazy_value(lazy) == 2
